def is_palindrome(text):
    clean_text_list = []
    for char in text:
        if 'a' <= char.lower() <= 'z' or '0' <= char <= '9':
            clean_text_list.append(char.lower())

    cleaned_text = "".join(clean_text_list)

    left = 0
    right = len(cleaned_text) - 1

    while left < right:
        if cleaned_text[left] != cleaned_text[right]:
            return False
        left = left + 1
        right = right - 1

    return True

