def validate_email(email):
    if not isinstance(email, str):
        return False

    at_pos = email.find('@')
    dot_pos = email.rfind('.')

    if at_pos == -1 or dot_pos == -1:
        return False

    if at_pos > dot_pos:
        return False

    if at_pos == 0 or dot_pos == len(email) - 1:
        return False

    if email.find('@', at_pos + 1) != -1:
        return False

    if dot_pos - at_pos < 2:  # Must have chars between @ and .
        return False

    return True

