def update_inventory(inventory, item_name, quantity):
    if item_name in inventory:
        inventory[item_name] = inventory[item_name] + quantity
    else:
        inventory[item_name] = quantity
    return inventory

def process_orders(initial_inventory, order_list):
    current_inventory = initial_inventory.copy()
    for item, qty in order_list:
        if qty > 0:
            current_inventory = update_inventory(current_inventory, item, qty)
        elif item in current_inventory and current_inventory[item] + qty >= 0:
            current_inventory[item] = current_inventory[item] + qty
        elif item in current_inventory and current_inventory[item] + qty < 0:
            current_inventory[item] = 0
    return current_inventory

