def most_frequent_char(text):
    freq_map = {}
    max_freq = 0
    most_freq_char_val = ''

    for char in text:
        if char == ' ':
            continue

        lower_char = char.lower()
        if lower_char in freq_map:
            freq_map[lower_char] += 1
        else:
            freq_map[lower_char] = 1

        current_freq = freq_map[lower_char]
        if current_freq > max_freq:
            max_freq = current_freq
            most_freq_char_val = lower_char

    # Re-iterate to handle ties by original appearance order
    # The first character encountered that has max_freq is the answer
    for char in text:
        if char == ' ':
            continue
        lower_char = char.lower()
        if freq_map[lower_char] == max_freq:
            return lower_char

    return most_freq_char_val

