def multiplication_table(n):
    table=[]
    for i in range(1, n+1):
        row=[]
        for j in range(1, n+1):
            product=i*j
            row.append(product)
        table.append(row)
    return table

def print_table_nicely(table):
    if not table:
        return

    max_val=table[-1][-1]
    max_len=len(str(max_val))

    for row in table:
        row_str=[]
        for element in row:
            padded_element=str(element).rjust(max_len)
            row_str.append(padded_element)
        print("  ".join(row_str))

