def binary_to_decimal(binary_string):
    decimal_value = 0
    power = 0
    reversed_string = binary_string[::-1]

    for digit_char in reversed_string:
        digit = int(digit_char)
        if digit == 1:
            decimal_value = decimal_value + (2 ** power)
        power = power + 1
    return decimal_value

